@ResponseBody
public AttackResult sendPasswordResetLink(@RequestParam String email, HttpServletRequest request, @CurrentUsername String username) throws URISyntaxException {
    if (!username.equals("admin") && !StringUtils.hasText(email)) {
        return success(this).feedback("email.invalid").build();
    }
    if (StringUtils.hasText(email)) {
        String usernameFromEmail = email.substring(0, email.indexOf("@"));
        if (StringUtils.hasText(usernameFromEmail) && usernameFromEmail.equals(username)) {
            URI uri = new URI(request.getRequestURL().toString());
            Email mail = Email.builder()
                .title("Your password reset link for challenge 7")
                .contents(String.format(TEMPLATE, uri.getScheme() + "://" + uri.getHost(), new PasswordResetLink().createPasswordReset(usernameFromEmail, "webgoat")))
                .sender("password-reset@webgoat-cloud.net")
                .recipient(usernameFromEmail)
                .time(LocalDateTime.now())
                .build();
            restTemplate.postForEntity(webWolfMailURL, mail, Object.class);
        } else {
            return success(this).feedback("email.mismatch").build();
        }
    }
    return success(this).feedback("email.send").feedbackArgs(email).build();
}

