 36| /** Controller for uploading a file */
 37| @Controller
 38| @Slf4j
 39| public class FileServer {
 40| 
 41|   private static final DateTimeFormatter dateTimeFormatter =
 42|       DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
 43| 
 44|   @Value("${webwolf.fileserver.location}")
 45|   private String fileLocation;
 46| 
 47|   @Value("${server.address}")
 48|   private String server;
 49| 
 50|   @Value("${server.servlet.context-path}")
 51|   private String contextPath;
 52| 
 53|   @Value("${server.port}")
 54|   private int port;
 55| 
 56|   @RequestMapping(
 57|       path = "/file-server-location",
 58|       consumes = ALL_VALUE,
 59|       produces = MediaType.TEXT_PLAIN_VALUE)
 60|   @ResponseBody
 61|   public String getFileLocation() {
 62|     return fileLocation;
 63|   }
 64| 
 65|   @PostMapping(value = "/fileupload")
 66|   public ModelAndView importFile(
 67|       @RequestParam("file") MultipartFile multipartFile, Authentication authentication)
 68|       throws IOException {
 69|     var username = authentication.getName();
 70|     var destinationDir = new File(fileLocation, username);
 71|     destinationDir.mkdirs();
 72|     // DO NOT use multipartFile.transferTo(), see
 73|     // https://stackoverflow.com/questions/60336929/java-nio-file-nosuchfileexception-when-file-transferto-is-called
 74|     try (InputStream is = multipartFile.getInputStream()) {
 75|       var destinationFile = destinationDir.toPath().resolve(multipartFile.getOriginalFilename());
 76|       Files.deleteIfExists(destinationFile);
 77|       Files.copy(is, destinationFile);
 78|     }
 79|     log.debug("File saved to {}", new File(destinationDir, multipartFile.getOriginalFilename()));
 80| 
 81|     return new ModelAndView(
 82|         new RedirectView("files", true),
 83|         new ModelMap().addAttribute("uploadSuccess", "File uploaded successful"));
 84|   }
 85| 
 86|   @GetMapping(value = "/files")
 87|   public ModelAndView getFiles(
 88|       HttpServletRequest request, Authentication authentication, TimeZone timezone) {
 89|     String username = (null != authentication) ? authentication.getName() : "anonymous";
 90|     File destinationDir = new File(fileLocation, username);
 91| 
 92|     ModelAndView modelAndView = new ModelAndView();
 93|     modelAndView.setViewName("files");
 94|     File changeIndicatorFile = new File(destinationDir, username + "_changed");
 95|     if (changeIndicatorFile.exists()) {
 96|       modelAndView.addObject("uploadSuccess", request.getParameter("uploadSuccess"));
 97|     }
 98|     changeIndicatorFile.delete();
 99| 
100|     record UploadedFile(String name, String size, String link, String creationTime) {}
101| 
102|     var uploadedFiles = new ArrayList<UploadedFile>();
103|     File[] files = destinationDir.listFiles(File::isFile);
104|     if (files != null) {
105|       for (File file : files) {
106|         String size = FileUtils.byteCountToDisplaySize(file.length());
107|         String link = String.format("files/%s/%s", username, file.getName());
108|         uploadedFiles.add(
109|             new UploadedFile(file.getName(), size, link, getCreationTime(timezone, file)));
110|       }
111|     }
112| 
113|     modelAndView.addObject(
114|         "files",
115|         uploadedFiles.stream().sorted(comparing(UploadedFile::creationTime).reversed()).toList());
116|     modelAndView.addObject("webwolf_url", "http://" + server + ":" + port + contextPath);
117|     return modelAndView;
118|   }
119| 
120|   private String getCreationTime(TimeZone timezone, File file) {
121|     try {
122|       FileTime creationTime = (FileTime) Files.getAttribute(file.toPath(), "creationTime");
123|       ZonedDateTime zonedDateTime = creationTime.toInstant().atZone(timezone.toZoneId());
124|       return dateTimeFormatter.format(zonedDateTime);
125|     } catch (IOException e) {
126|       return "unknown";
127|     }
128|   }
