    long now = System.currentTimeMillis();
    synchronized (rateLimitMap) {
        rateLimitMap.entrySet().removeIf(e -> now - e.getValue() > 60_000);
        int count = rateLimitMap.getOrDefault(ip, 0);
        if (count >= 10) return true;
        rateLimitMap.put(ip, now);
        return false;
    }
}

