    // Add rate limiting per IP (simple in-memory counter - production should use Redis)
    String clientIp = getClientIp(request);
    if (isRateLimited(clientIp)) {
        return failed(this).feedback("spoofcookie.rate_limited").build();
    }

    if (StringUtils.isEmpty(cookieValue)) {
        return credentialsLoginFlow(username, password, response);
    } else {
        return cookieLoginFlow(cookieValue);
    }
}

// Add helper methods
private String getClientIp(HttpServletRequest request) {
    String xForwardedFor = request.getHeader("X-Forwarded-For");
    return xForwardedFor != null && !xForwardedFor.isEmpty() ? xForwardedFor.split(",")[0].trim() : request.getRemoteAddr();
}

private boolean isRateLimited(String ip) {
    // In production: use Redis with TTL (e.g., 10 req/minute)
    // Here: simple static map for demo
    long now = System.currentTimeMillis();
    synchronized (rateLimitMap) {
        rateLimitMap.entrySet().removeIf(e -> now - e.getValue() > 60_000);
        int count = rateLimitMap.getOrDefault(ip, 0);
        if (count >= 10) return true;
        rateLimitMap.put(ip, now);
        return false;
    }
}

private static final Map<String, Long> rateLimitMap = new ConcurrentHashMap<>();

