    // ✅ ADD: Require server-side session state or signed token
    // For teaching context, enforce that only cookies issued by /login are valid
    // Here: simulate a simple HMAC signature check (real fix requires secure signing)
    String expectedSignature = hmacSign(cookieUsername, "webgoat-secret-key");
    if (!isValidSignature(cookieValue, expectedSignature)) {
        return failed(this).feedback("spoofcookie.cookie-tampered").build();
    }
    if (cookieUsername.equals(ATTACK_USERNAME)) {
        return success(this).build();
    }
    return failed(this).feedback("spoofcookie.cookie-login").build();
}

