public void login(@RequestParam("user") String user, HttpServletResponse response) {
    // ✅ 修复：精确白名单校验，拒绝子串匹配
    Set<String> allowedUsers = Set.of("Tom", "Jerry", "Sylvester");
    if (!allowedUsers.contains(user)) {
        Cookie cookie = new Cookie("access_token", "");
        cookie.setMaxAge(0);
        cookie.setPath("/");
        response.addCookie(cookie);
        response.setStatus(HttpStatus.UNAUTHORIZED.value());
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        return;
    }
    Claims claims = Jwts.claims().setIssuedAt(Date.from(Instant.now()));
    claims.setExpiration(Date.from(Instant.now().plus(Duration.ofMinutes(30)))); // ✅ 强制 exp
    claims.put("admin", "false");
    claims.put("user", user);
    // ✅ 使用强密钥（从环境变量加载，此处示意）
    String jwtSecret = System.getenv("JWT_SECRET");
    if (jwtSecret == null || jwtSecret.length() < 32) {
        throw new IllegalStateException("JWT_SECRET must be >= 32 chars");
    }
    String token = Jwts.builder()
            .setClaims(claims)
            .signWith(SignatureAlgorithm.HS512, jwtSecret.getBytes(StandardCharsets.UTF_8))
            .compact();
    Cookie cookie = new Cookie("access_token", token);
    cookie.setHttpOnly(true);
    cookie.setSecure(true); // ✅ HTTPS only
    cookie.setPath("/");
    cookie.setMaxAge(30 * 60); // ✅ 30 min TTL
    response.addCookie(cookie);
    response.setStatus(HttpStatus.OK.value());
    response.setContentType(MediaType.APPLICATION_JSON_VALUE);
}

