@ResponseBody
public ResponseEntity<?> getProfilePicture(HttpServletRequest request, @CurrentUsername String username) {
    var queryParams = request.getQueryString();
    if (queryParams != null && (queryParams.contains("..") || queryParams.contains("/"))) {
        return ResponseEntity.badRequest()
            .body("Illegal characters are not allowed in the query params");
    }
    try {
        var id = request.getParameter("id");
        // 强制绑定用户上下文：仅允许访问以 username 哈希命名的专属图片（如 guest.jpg），或引入用户专属子目录
        String safeId = (id == null ? String.valueOf(RandomUtils.nextInt(1, 11)) : id);
        // 示例修复：限定 id 必须为当前用户专属（如 username + "_profile.jpg"），或改用用户绑定路径
        File catPicture = new File(catPicturesDirectory, safeId + ".jpg");

        // 关键修复：校验文件是否在预期目录下（防御路径遍历）且归属当前用户（IDOR）
        if (!catPicture.getCanonicalPath().startsWith(catPicturesDirectory.getCanonicalPath())) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN).build();
        }

        // IDOR 修复：此处应关联用户，例如：
        // if (!safeId.equals(Sha512DigestUtils.shaHex(username).substring(0, 10))) { ... }
        // 或更合理：将图片按用户存储，如 new File(catPicturesDirectory, username + "/" + safeId + ".jpg")

        if (catPicture.getName().toLowerCase().contains("path-traversal-secret.jpg")) {
            return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(MediaType.IMAGE_JPEG_VALUE))
                .body(FileCopyUtils.copyToByteArray(catPicture));
        }
        if (catPicture.exists()) {
            return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(MediaType.IMAGE_JPEG_VALUE))
                .location(new URI("/PathTraversal/random-picture?id=" + catPicture.getName()))
                .body(Base64.getEncoder().encode(FileCopyUtils.copyToByteArray(catPicture)));
        }
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
            .location(new URI("/PathTraversal/random-picture?id=" + catPicture.getName()))
            .body(
                StringUtils.arrayToCommaDelimitedString(catPicture.getParentFile().listFiles())
                    .getBytes());
    } catch (IOException | URISyntaxException e) {
        log.error("Image not found", e);
    }
    return ResponseEntity.badRequest().build();
}

